import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v6_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [novoProc, setNovoProc] = useState({ 
    cliente: '', numero: '', valor: '', data: '', status: 'Ativo', area: 'Cível' 
  });

  useEffect(() => {
    localStorage.setItem('juris_v6_data', JSON.stringify(processos));
  }, [processos]);

  // Lógica de cálculo de prazo CPC (15 dias úteis)
  const calcularPrazoFinal = (dataInicio) => {
    if (!dataInicio) return null;
    let data = new Date(dataInicio + 'T00:00:00');
    let diasContados = 0;
    while (diasContados < 15) {
      data.setDate(data.getDate() + 1);
      if (data.getDay() !== 0 && data.getDay() !== 6) diasContados++;
    }
    return data;
  };

  const addProcesso = () => {
    if (!novoProc.cliente || !novoProc.valor) return alert("Preencha os campos obrigatórios!");
    setProcessos([...processos, { ...novoProc, id: Date.now() }]);
    setNovoProc({ cliente: '', numero: '', valor: '', data: '', status: 'Ativo', area: 'Cível' });
    setTab('agenda');
  };

  return (
    <div style={s.app}>
      {/* SIDEBAR PREMIUM */}
      <aside style={s.sidebar}>
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'agenda')} onClick={() => setTab('agenda')}>📅 Agenda de Prazos</div>
          <div style={s.navLink(tab === 'novo')} onClick={() => setTab('novo')}>➕ Novo Registro</div>
        </nav>
        <div style={s.systemStatus}>
          <div style={s.dot} /> <span>SERVIDOR BRAZIL-01: ATIVO</span>
        </div>
      </aside>

      <main style={s.content}>
        <header style={s.header}>
          <div>
            <h2 style={{margin: 0}}>Central de Operações</h2>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>Monitoramento de fluxos e prazos fatais.</p>
          </div>
          <div style={s.dateBadge}>{new Date().toLocaleDateString('pt-BR', {dateStyle: 'long'})}</div>
        </header>

        {/* DASHBOARD RESUMIDO */}
        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Patrimônio sob Gestão" value={`R$ ${processos.reduce((a,b)=>a+Number(b.valor),0).toLocaleString()}`} color={COLORS.success} />
            <StatCard label="Prazos Pendentes" value={processos.filter(p=>p.data).length} color={COLORS.gold} />
            <StatCard label="Taxa de Sucesso" value="92%" color={COLORS.accent} />
            
            <div style={{...s.card, gridColumn: 'span 3'}}>
              <h4>Fluxo Mensal de Novos Casos</h4>
              <div style={{display: 'flex', alignItems: 'flex-end', gap: '15px', height: '120px', paddingBottom: '10px'}}>
                {[40, 70, 45, 90, 65, 80, 100, 50, 30, 85].map((h, i) => (
                  <div key={i} style={{...s.bar, height: `${h}%`}} />
                ))}
              </div>
            </div>
          </div>
        )}

        {/* AGENDA INTELIGENTE */}
        {tab === 'agenda' && (
          <div style={s.card}>
            <h3 style={{marginTop: 0, color: COLORS.accent}}>🗓️ Próximos Vencimentos (CPC/15)</h3>
            <div style={s.tableContainer}>
              <table style={s.table}>
                <thead>
                  <tr>
                    <th style={s.th}>CLIENTE</th>
                    <th style={s.th}>DATA INICIAL</th>
                    <th style={s.th}>PRAZO FINAL (FATAL)</th>
                    <th style={s.th}>STATUS</th>
                  </tr>
                </thead>
                <tbody>
                  {processos.filter(p => p.data).map(p => {
                    const prazoFinal = calcularPrazoFinal(p.data);
                    return (
                      <tr key={p.id}>
                        <td style={s.td}><strong>{p.cliente}</strong></td>
                        <td style={s.td}>{new Date(p.data + 'T00:00:00').toLocaleDateString()}</td>
                        <td style={s.td}><span style={s.dateCritical}>{prazoFinal.toLocaleDateString()}</span></td>
                        <td style={s.td}><span style={s.badge}>Aguardando Petição</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              {processos.filter(p => p.data).length === 0 && (
                <p style={{textAlign: 'center', padding: '40px', color: COLORS.muted}}>Nenhum prazo cadastrado.</p>
              )}
            </div>
          </div>
        )}

        {/* FORMULÁRIO DE CADASTRO */}
        {tab === 'novo' && (
          <div style={{...s.card, maxWidth: '500px', margin: '0 auto'}}>
            <h3 style={{marginTop: 0}}>📝 Registrar Caso e Prazo</h3>
            <label style={s.label}>Nome do Cliente</label>
            <input style={s.input} value={novoProc.cliente} onChange={e => setNovoProc({...novoProc, cliente: e.target.value})} />
            
            <label style={s.label}>Área de Atuação</label>
            <select style={s.input} value={novoProc.area} onChange={e => setNovoProc({...novoProc, area: e.target.value})}>
              <option value="Cível">Cível</option>
              <option value="Trabalhista">Trabalhista</option>
              <option value="Tributário">Tributário</option>
            </select>

            <label style={s.label}>Honorários (R$)</label>
            <input style={s.input} type="number" value={novoProc.valor} onChange={e => setNovoProc({...novoProc, valor: e.target.value})} />

            <label style={s.label}>Data da Intimação (Início do Prazo)</label>
            <input style={s.input} type="date" value={novoProc.data} onChange={e => setNovoProc({...novoProc, data: e.target.value})} />
            
            <button style={s.btnMain} onClick={addProcesso}>SALVAR E GERAR PRAZO</button>
          </div>
        )}
      </main>
    </div>
  );
}

// ESTILOS COMPLEMENTARES
const StatCard = ({label, value, color}) => (
  <div style={s.card}>
    <div style={{color: COLORS.muted, fontSize: '11px', fontWeight: 'bold'}}>{label.toUpperCase()}</div>
    <div style={{fontSize: '28px', fontWeight: 'bold', color: color, margin: '12px 0'}}>{value}</div>
  </div>
);

const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: "'Inter', sans-serif" },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '30px 20px' },
  brand: { fontSize: '22px', fontWeight: 'bold', color: COLORS.accent, display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '40px' },
  brandIcon: { width: '32px', height: '32px', backgroundColor: COLORS.accent, color: 'white', borderRadius: '6px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: '900' },
  nav: { flex: 1 },
  navLink: (active) => ({ padding: '14px 18px', borderRadius: '12px', cursor: 'pointer', marginBottom: '10px', color: active ? COLORS.accent : COLORS.muted, backgroundColor: active ? 'rgba(56, 189, 248, 0.08)' : 'transparent', transition: '0.2s', fontSize: '14px' }),
  systemStatus: { display: 'flex', alignItems: 'center', gap: '8px', fontSize: '10px', color: COLORS.muted, padding: '15px', borderTop: `1px solid ${COLORS.border}` },
  dot: { width: '8px', height: '8px', backgroundColor: COLORS.success, borderRadius: '50%' },
  content: { flex: 1, padding: '40px', overflowY: 'auto' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px' },
  dateBadge: { padding: '10px 20px', backgroundColor: COLORS.card, borderRadius: '30px', border: `1px solid ${COLORS.border}`, fontSize: '13px' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' },
  card: { backgroundColor: COLORS.card, padding: '30px', borderRadius: '20px', border: `1px solid ${COLORS.border}` },
  tableContainer: { marginTop: '20px' },
  table: { width: '100%', borderCollapse: 'collapse' },
  th: { textAlign: 'left', padding: '12px', color: COLORS.muted, fontSize: '11px', borderBottom: `1px solid ${COLORS.border}` },
  td: { padding: '15px', borderBottom: `1px solid ${COLORS.border}`, fontSize: '14px' },
  dateCritical: { color: COLORS.danger, fontWeight: 'bold', padding: '4px 8px', backgroundColor: 'rgba(239, 68, 68, 0.1)', borderRadius: '6px' },
  badge: { fontSize: '11px', padding: '4px 8px', backgroundColor: '#1e293b', borderRadius: '4px', color: COLORS.muted },
  label: { display: 'block', fontSize: '12px', color: COLORS.muted, marginBottom: '8px', marginTop: '15px' },
  input: { width: '100%', padding: '12px', backgroundColor: '#000', border: `1px solid ${COLORS.border}`, color: 'white', borderRadius: '10px' },
  btnMain: { width: '100%', padding: '15px', backgroundColor: COLORS.accent, color: '#000', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer', marginTop: '25px' },
  bar: { flex: 1, backgroundColor: COLORS.accent, borderRadius: '4px 4px 0 0', opacity: 0.6 }
};
